[package]
name = "cli-tool"
version = "0.1.0"
edition = "2021"

[dependencies]
clap = { version = "4.4", features = ["derive"] }
serde = { version = "1.0", features = ["derive"] }
tokio = { version = "1.32", features = ["full"] }

{
  "name": "browser-extension",
  "version": "1.0.0",
  "description": "A tab sorting browser extension",
  "scripts": {
    "test": "jest",
    "build": "webpack --mode production"
  },
  "devDependencies": {
    "jest": "^29.0.0",
    "webpack": "^5.88.0"
  }
}

document.getElementById('sort-btn').addEventListener('click', async () => {
  const tabs = await chrome.tabs.query({ currentWindow: true });
  tabs.sort((a, b) => a.title.localeCompare(b.title));
  const sortedIds = tabs.map(t => t.id);
  await chrome.tabs.move(sortedIds, { index: 0 });
  window.close();
});
